reference_solution.python:
class Solution:
    def subarraySum(self, nums: List[int], k: int) -> int:
        res = 0
        cur_sum = 0
        prefix_sums = {0: 1}
        for n in nums:
            cur_sum += n
            diff = cur_sum - k
            res += prefix_sums.get(diff, 0)
            prefix_sums[cur_sum] = prefix_sums.get(cur_sum, 0) + 1
        return res

reference_solution.javascript:
function subarraySum(nums, k) {
    let res = 0, curSum = 0;
    const map = new Map();
    map.set(0, 1);
    for (const n of nums) {
        curSum += n;
        const diff = curSum - k;
        if (map.has(diff)) res += map.get(diff);
        map.set(curSum, (map.get(curSum) || 0) + 1);
    }
    return res;
}
